import { describe, expect, it } from "vitest";
import { isChatModel, selectChatModels } from "../src/catalogFilter";
import type { OmniRouteModel } from "../src/types";

const model = (over: Partial<OmniRouteModel> & { id: string }): OmniRouteModel => over;

describe("isChatModel", () => {
  it("keeps rows with no type — that is how OmniRoute marks chat models", () => {
    expect(isChatModel(model({ id: "cc/claude-sonnet-4-6" }))).toBe(true);
  });

  it('keeps an explicit type "chat" (and ignores case/padding)', () => {
    expect(isChatModel(model({ id: "a", type: "chat" }))).toBe(true);
    expect(isChatModel(model({ id: "b", type: " Chat " }))).toBe(true);
  });

  it("drops specialty registries that cannot answer a chat request", () => {
    for (const type of ["audio", "image", "embedding", "rerank", "video", "moderation"]) {
      expect(isChatModel(model({ id: `x/${type}`, type }))).toBe(false);
    }
  });

  // Regression guard: OmniRoute lists every Codex/GPT-5.x model as
  // `supported_endpoints: ["responses"]` and translates them for
  // chat/completions. Verified live on 192.168.0.17 — `cx/gpt-5.5-low` and
  // `cx/gpt-5.6-sol-low` both answer HTTP 200. Filtering on "does not include
  // chat" would silently drop 26 usable models from the picker.
  it("keeps a Responses-API model — OmniRoute translates it for chat", () => {
    expect(isChatModel(model({ id: "cx/gpt-5.6-sol-low", supported_endpoints: ["responses"] }))).toBe(
      true
    );
  });

  it("keeps a multi-surface model as long as one surface is conversational", () => {
    expect(isChatModel(model({ id: "m", supported_endpoints: ["chat", "responses"] }))).toBe(true);
  });

  it("drops an untyped row that declares only non-conversational surfaces", () => {
    expect(isChatModel(model({ id: "x/embed", supported_endpoints: ["embeddings"] }))).toBe(false);
  });

  it("still drops a typed specialty row even if it claims a chat surface", () => {
    expect(isChatModel(model({ id: "x/img", type: "image", supported_endpoints: ["chat"] }))).toBe(
      false
    );
  });

  it("keeps a model with an empty endpoint list rather than guessing it is unusable", () => {
    expect(isChatModel(model({ id: "m", supported_endpoints: [] }))).toBe(true);
  });
});

describe("selectChatModels", () => {
  it("drops the canonical mirror emitted by dual prefix mode", () => {
    const models = [
      model({ id: "cc/claude-sonnet-4-6", parent: null }),
      model({ id: "claude/claude-sonnet-4-6", parent: "cc/claude-sonnet-4-6" }),
    ];
    expect(selectChatModels(models).map((m) => m.id)).toEqual(["cc/claude-sonnet-4-6"]);
  });

  it("keeps a row whose parent is not itself listed — never lose a model", () => {
    const models = [model({ id: "solo/model", parent: "absent/model" })];
    expect(selectChatModels(models).map((m) => m.id)).toEqual(["solo/model"]);
  });

  it("keeps a row that points at itself", () => {
    const models = [model({ id: "self/model", parent: "self/model" })];
    expect(selectChatModels(models).map((m) => m.id)).toEqual(["self/model"]);
  });

  it("preserves catalog order and skips entries without an id", () => {
    const models = [
      model({ id: "a" }),
      { } as OmniRouteModel,
      model({ id: "b" }),
      model({ id: "c" }),
    ];
    expect(selectChatModels(models).map((m) => m.id)).toEqual(["a", "b", "c"]);
  });

  it("combines both rules: specialty rows and mirrors go, chat models stay", () => {
    const models = [
      model({ id: "cc/claude-sonnet-4-6" }),
      model({ id: "claude/claude-sonnet-4-6", parent: "cc/claude-sonnet-4-6" }),
      model({ id: "openai/whisper-1", type: "audio" }),
      model({ id: "auto/best-free" }),
    ];
    expect(selectChatModels(models).map((m) => m.id)).toEqual([
      "cc/claude-sonnet-4-6",
      "auto/best-free",
    ]);
  });
});

import { describe, expect, it } from "vitest";
import {
  REASONING_EFFORTS,
  isReasoningModel,
  normalizeReasoningEffort,
  resolveReasoningEffort,
} from "../src/reasoning";

describe("normalizeReasoningEffort", () => {
  it("accepts every canonical tier", () => {
    for (const tier of REASONING_EFFORTS) {
      expect(normalizeReasoningEffort(tier)).toBe(tier);
    }
  });

  it("is case- and whitespace-insensitive", () => {
    expect(normalizeReasoningEffort("  HIGH ")).toBe("high");
  });

  it("collapses the top-tier synonyms onto xhigh", () => {
    expect(normalizeReasoningEffort("max")).toBe("xhigh");
    expect(normalizeReasoningEffort("extra")).toBe("xhigh");
    expect(normalizeReasoningEffort("ultra")).toBe("xhigh");
  });

  it("maps OpenAI's 'minimal' onto low instead of forwarding it verbatim", () => {
    // `minimal` is not in OmniRoute's canonical set, so passing it through
    // would reach providers that reject it.
    expect(normalizeReasoningEffort("minimal")).toBe("low");
  });

  it("returns undefined for anything unrecognized, so the request stays untouched", () => {
    for (const value of ["", "   ", "turbo", "7", null, undefined, 3, {}, []]) {
      expect(normalizeReasoningEffort(value)).toBeUndefined();
    }
  });
});

describe("isReasoningModel", () => {
  it("accepts either capability flag — providers disagree on the name", () => {
    expect(isReasoningModel({ capabilities: { reasoning: true } })).toBe(true);
    expect(isReasoningModel({ capabilities: { thinking: true } })).toBe(true);
  });

  it("is false when absent or explicitly false", () => {
    expect(isReasoningModel({})).toBe(false);
    expect(isReasoningModel({ capabilities: {} })).toBe(false);
    expect(isReasoningModel({ capabilities: { reasoning: false, thinking: false } })).toBe(false);
  });
});

describe("resolveReasoningEffort", () => {
  it("takes the editor's per-request value from any of the accepted shapes", () => {
    const shapes = [
      { reasoning_effort: "high" },
      { reasoningEffort: "high" },
      { reasoning: { effort: "high" } },
      { effort: "high" },
    ];
    for (const modelOptions of shapes) {
      expect(resolveReasoningEffort({ modelOptions, modelIsReasoning: true })).toBe("high");
    }
  });

  it("lets the editor's choice win over the configured default", () => {
    expect(
      resolveReasoningEffort({
        modelOptions: { reasoning_effort: "low" },
        configuredDefault: "high",
        modelIsReasoning: true,
      })
    ).toBe("low");
  });

  it("applies the configured default to reasoning-capable models", () => {
    expect(
      resolveReasoningEffort({ configuredDefault: "medium", modelIsReasoning: true })
    ).toBe("medium");
  });

  it("never applies the configured default to a model without thinking support", () => {
    // Sending reasoning_effort to a non-thinking model is ignored at best and a
    // 400 at worst, so the default must not leak onto the whole catalog.
    expect(
      resolveReasoningEffort({ configuredDefault: "high", modelIsReasoning: false })
    ).toBeUndefined();
  });

  it("still forwards an explicit request even when the catalog says non-reasoning", () => {
    // The catalog can be stale or incomplete; an explicit user choice is a
    // stronger signal than a missing capability flag.
    expect(
      resolveReasoningEffort({
        modelOptions: { reasoning_effort: "high" },
        modelIsReasoning: false,
      })
    ).toBe("high");
  });

  it("returns undefined when nothing is configured or requested", () => {
    expect(resolveReasoningEffort({ modelIsReasoning: true })).toBeUndefined();
    expect(
      resolveReasoningEffort({ modelOptions: {}, configuredDefault: "", modelIsReasoning: true })
    ).toBeUndefined();
  });

  it("ignores a garbage default instead of forwarding it", () => {
    expect(
      resolveReasoningEffort({ configuredDefault: "very-high", modelIsReasoning: true })
    ).toBeUndefined();
  });
});

import { describe, expect, it } from "vitest";
import * as vscode from "vscode";
import {
  estimateTokens,
  extractToolResultText,
  isEmptyContent,
  toOpenAiMessages,
  toOpenAiTools,
} from "../src/convert";
import { normalizeBaseUrl, serverRootUrl } from "../src/client";

type AnyMessage = Parameters<typeof toOpenAiMessages>[0][number];

function msg(role: vscode.LanguageModelChatMessageRole, content: unknown[]): AnyMessage {
  return { role, content } as unknown as AnyMessage;
}

describe("toOpenAiMessages", () => {
  it("converts a plain user text message to a string content", () => {
    const out = toOpenAiMessages([
      msg(vscode.LanguageModelChatMessageRole.User, [
        new vscode.LanguageModelTextPart("hello"),
      ]),
    ]);
    expect(out).toEqual([{ role: "user", content: "hello" }]);
  });

  it("maps roles including system", () => {
    const out = toOpenAiMessages([
      msg(vscode.LanguageModelChatMessageRole.System, [
        new vscode.LanguageModelTextPart("be brief"),
      ]),
      msg(vscode.LanguageModelChatMessageRole.Assistant, [
        new vscode.LanguageModelTextPart("ok"),
      ]),
    ]);
    expect(out.map((m) => m.role)).toEqual(["system", "assistant"]);
  });

  it("drops empty messages", () => {
    const out = toOpenAiMessages([
      msg(vscode.LanguageModelChatMessageRole.User, [new vscode.LanguageModelTextPart("  ")]),
    ]);
    expect(out).toEqual([]);
  });

  it("converts assistant tool calls with null content when there is no text", () => {
    const out = toOpenAiMessages([
      msg(vscode.LanguageModelChatMessageRole.Assistant, [
        new vscode.LanguageModelToolCallPart("call_1", "read_file", { path: "a.ts" }),
      ]),
    ]);
    expect(out).toEqual([
      {
        role: "assistant",
        content: null,
        tool_calls: [
          {
            id: "call_1",
            type: "function",
            function: { name: "read_file", arguments: '{"path":"a.ts"}' },
          },
        ],
      },
    ]);
  });

  it("expands tool results into role:tool messages keeping callId", () => {
    const out = toOpenAiMessages([
      msg(vscode.LanguageModelChatMessageRole.User, [
        new vscode.LanguageModelToolResultPart("call_1", [
          new vscode.LanguageModelTextPart("file contents"),
        ]),
      ]),
    ]);
    expect(out).toEqual([
      { role: "tool", content: "file contents", tool_call_id: "call_1" },
    ]);
  });

  it("converts image data parts into data URLs", () => {
    const bytes = new Uint8Array([1, 2, 3]);
    const out = toOpenAiMessages([
      msg(vscode.LanguageModelChatMessageRole.User, [
        new vscode.LanguageModelTextPart("what is this?"),
        vscode.LanguageModelDataPart.image(bytes, "image/png"),
      ]),
    ]);
    expect(Array.isArray(out[0].content)).toBe(true);
    const parts = out[0].content as Array<{ type: string; image_url?: { url: string } }>;
    expect(parts[0]).toEqual({ type: "text", text: "what is this?" });
